#!/usr/bin/env bash
# Fixes a real bug in the Agent's automatic rollback flow
# (agent/update_manager.py) that made every rollback's status get stuck
# forever on the Admin Panel, even though the actual rollback worked fine
# on the kiosk.
#
# ROOT CAUSE: the Admin Panel's deployment state machine
# (ALLOWED_TRANSITIONS in app/models.py) requires:
#   health_check -> failed -> rolling_back -> rolled_back/failed
# But _attempt_rollback() tried to report "rolling_back" directly from
# "health_check" — a transition the server has never allowed. Every such
# report was rejected with HTTP 409 and silently swallowed (by design —
# a reporting failure must never block the actual local recovery), so the
# kiosk would recover correctly but the Admin Panel's deployment record
# would sit stuck showing "Health check" forever, never advancing to
# "Rolling back" or a final "Rolled back"/"Failed".
#
# CONFIRMED both the bug and the fix against a real running server before
# this was shipped — built two real kiosk-app packages (one good, one
# that crashes on start), deployed the good one successfully, then pushed
# the bad one and drove the actual Agent code (not a mock) through a full
# rollback:
#   - Before the fix: deployment got stuck at "health_check", the 409
#     rejection logged on every attempt, despite the kiosk correctly
#     recovering locally.
#   - After the fix: full correct chain confirmed end-to-end -
#     health_check -> failed -> rolling_back -> rolled_back: "restored
#     and verified healthy at v9.9.3" - with the kiosk's own HTTP health
#     endpoint actually responding 200 after the restore, not just a
#     status flag saying so.
#
# Includes a rebuilt app/static/installers/opslab-agent.tar.gz (this is
# an agent/ file, so it needs Publishing to reach new installs - already
# done here). Already-enrolled kiosks still need a reinstall to pick this
# up, same caveat as every prior agent-side fix this session.
#
# No database migration in this push.
#
# Run from inside /root/admin_panel.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"

for req in agent requirements.txt run.py; do
    if [ ! -e "$req" ]; then
        echo "Error: expected to find '$req' here - run this from the admin_panel repo root."
        exit 1
    fi
done

TS="$(date +%Y%m%d_%H%M%S)"
mkdir -p "backups/$TS"
cp agent/update_manager.py "backups/$TS/update_manager.py.bak" 2>/dev/null || true
cp app/static/installers/opslab-agent.tar.gz "backups/$TS/opslab-agent.tar.gz.bak" 2>/dev/null || true
echo "==> Backed up existing files to backups/$TS/"

echo "==> Writing agent/update_manager.py"
base64 -d > agent/update_manager.py << 'UPDATE_MANAGER_PY_B64'

UPDATE_MANAGER_PY_B64

echo "==> Rewriting app/static/installers/opslab-agent.tar.gz (this fix is in agent/, needs publishing)"
base64 -d > app/static/installers/opslab-agent.tar.gz << 'AGENT_TAR_B64'

AGENT_TAR_B64

echo "==> Verifying"
python3 -c "import ast; ast.parse(open('agent/update_manager.py').read())"
echo "    syntax OK"
tar -tzf app/static/installers/opslab-agent.tar.gz > /dev/null
echo "    served agent tarball is readable"

echo ""
echo "==> Restarting the admin panel app"
pkill -f "admin_panel/run.py" 2>/dev/null || true
fuser -k 6090/tcp 2>/dev/null || true
sleep 1
source venv/bin/activate
nohup python run.py > app.log 2>&1 &
disown
sleep 2
tail -n 15 app.log

echo ""
echo "==================================================================="
echo "Fixed: automatic rollback deployments will now correctly show"
echo "'Rolling back' then a final 'Rolled back'/'Failed' status instead of"
echo "getting stuck on 'Health check' forever."
echo ""
echo "IMPORTANT - as with every prior agent-side fix: already-enrolled"
echo "kiosks need the Agent reinstalled (re-run install.sh/install.ps1) to"
echo "pick this up. New installs get it immediately."
echo "==================================================================="
